namespace ghidra.app.plugin.core.codebrowser.hover;





using docking.widgets.fieldpanel.field;
using docking.widgets.fieldpanel.support;
using ghidra;
using ghidra.app.plugin.core.hover;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.model.scalar;
using ghidra.program.util;
using ghidra.program.util;

public class ScalarOperandListingHover : AbstractScalarOperandHover, ListingHoverService {

	private static readonly int PRIORITY = 20;
	private static readonly string NAME = "Scalar Operand Display";
	private static readonly string DESCRIPTION =
		"Scalars are shown as 1-, 2-, 4-, and 8-byte values, each in decimal, hexadecimal, and " +
			"as ASCII character sequences.";

	public ScalarOperandListingHover(PluginTool tool) : base(tool, PRIORITY)
    {
	}

	/* @Override */
	protected string getName() {
		return NAME;
	}

	/* @Override */
	protected string getDescription() {
		return DESCRIPTION;
	}

	/* @Override */
	protected string getOptionsCategory() {
		return GhidraOptions.CATEGORY_BROWSER_POPUPS;
	}

	/* @Override */
	public JComponent getHoverComponent(Program program, ProgramLocation programLocation,
			FieldLocation fieldLocation, Field field) {

		if (!enabled || programLocation == null) {
			return null;
		}

		if (!(programLocation is OperandFieldLocation)) {
			return null;
		}

		Address a = programLocation.getAddress();
		Instruction instruction = program.getListing().getInstructionAt(a);
		if (instruction == null) {
			return null;
		}

		OperandFieldLocation operandLocation = (OperandFieldLocation) programLocation;
		object operand = getOperand(operandLocation, instruction);
		if (!(operand is Scalar)) {
			return null;
		}

		string formatted =
			formatScalar(instruction.getProgram(), instruction.getAddress(), (Scalar) operand);
		return createTooltipComponent(formatted);
	}

	private object getOperand(OperandFieldLocation loc, Instruction instruction) {
		int opIndex = loc.getOperandIndex();
		object[] operands = instruction.getOpObjects(opIndex);
		if (operands.length == 1) {
			return operands[0];
		}

		List<object> list = instruction.getDefaultOperandRepresentationList(opIndex);
		if (list == null) {
			return null;
		}
		// make sure operand sub-opIndex is in bounds
		int subOpIndex = loc.getSubOperandIndex();
		if (subOpIndex < 0 || subOpIndex >= list.size()) {
			return null;
		}
		return list.get(subOpIndex);
	}

}
